  private void CompleteFireBoss(){foreach(Enemy e in enemies){if(e.warning!=null)Destroy(e.warning);Destroy(e.root);if(e.shadow!=null)Destroy(e.shadow);}enemies.Clear();foreach(PendingSpawn p in pendingSpawns)if(p.mark!=null)Destroy(p.mark);pendingSpawns.Clear();foreach(Shot shot in shots)if(shot.root!=null)Destroy(shot.root);shots.Clear();ClearChapterSkillEffects();float oldCap=EffectiveMaximumShield;ClearJourneyRoom();chapterStone=true;journeyComplete=false;if(journeyRooms[currentRoom].stage==2){fireHeartRecovered=true;TellStory("赤潮熔龟胸前的紫纹裂开，火石落在少年掌心。它收拢岩甲，让出通往海岸的旧路。","阿铎：热流已经肯走旧渠了。东侧石廊里还有人在等，先把他们带回家。");BuildChapterActions();UpdateExplorationDoors();RequestCheckpoint();SaveChapterCheckpoint(false);return;}if(journeyRooms[currentRoom].stage==1){shield=Mathf.Min(EffectiveMaximumShield,shield+Mathf.Max(0,EffectiveMaximumShield-oldCap));TellStory("巨匠胸前的炉芯暗了下来。锁链停在半空，刚刚落稳的撤离桥没有再被热浪掀起。","阿铎：工坊的路通了。我替你补好护具，接下来的地心炉门，还得靠我们自己去打开。");AnnounceDiscovery("炉锻护具 · 护盾上限 +1");BuildChapterActions();UpdateExplorationDoors();RequestCheckpoint();SaveChapterCheckpoint(false);return;}TellStory("赤脊熔蜥背上的熔壳暗了下来。它拖着疲惫的尾巴，退进温热的岩洞。","少年：路可以走了。沿东侧炉道去训练炉，再把消息带回港口。");BuildChapterActions();UpdateExplorationDoors();RequestCheckpoint();SaveChapterCheckpoint(false);}
